schema_ddl:
CREATE TABLE contratti_assicurativi (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_polizza TEXT NOT NULL UNIQUE,
    data_inizio DATE NOT NULL,
    data_fine DATE,
    premio NUMERIC(10,2) NOT NULL CHECK (premio >= 0)
);

CREATE TABLE tid (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    data_nascita DATE NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE
);

CREATE TABLE coperture (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    descrizione TEXT NOT NULL,
    importo_massimo NUMERIC(12,2) NOT NULL CHECK (importo_massimo >= 0),
    polizza_id INT NOT NULL REFERENCES contratti_assicurativi(id)
);

CREATE TABLE polizze_tid (
    polizza_id INT NOT NULL REFERENCES contratti_assicurativi(id),
    assicurato_id INT NOT NULL REFERENCES tid(id),
    PRIMARY KEY (polizza_id, assicurato_id)
);
